	for (const name of listMarkdown(plansDir)) {
		const src = path.join(plansDir, name);
		if (!fs.statSync(src).isFile()) continue;
		if (!/^상태:\s*done$/m.test(readUtf8(src))) continue;
		const dest = freeName(archiveDir, name, stamp);
		fs.renameSync(src, path.join(archiveDir, dest));
		archived.push({ name, dest });
	}
	return archived;
}

/** `taskLines()` 와 같은 판정 — 들여쓴 체크리스트 항목(`  - [ ] 하위`)도 항목으로 본다. */
const isChecklistLine = (line: string): boolean => line.trim().startsWith("- [");

export interface AdvancedPlan {
	text: string;
	/** The Now item that was completed, without its checklist prefix. */
	completed: string;
	/** The Next item promoted into Now, without its checklist prefix; `""` when Next had none. */
	promoted: string;
}

/**
 * One step of the plan: the first Now checklist item moves to the end of `## Done` as `- [x] …`,
 * the first Next checklist item is promoted into Now, and 상태/마지막 갱신 are bumped.
 * Returns null — and nothing is changed — when Now has no checklist line.
 */
export function advancePlanText(text: string, stamp: string): AdvancedPlan | null {
	// 섹션을 원본 줄 그대로 읽고 항목만 splice 한다 — 걸러 읽고 통째로 덮어쓰면
	// 사용자가 Now/Next 에 적어 둔 메모 줄과 들여쓴 하위 항목이 사라진다.
	const now = sectionLines(text, "Now");
	const nowIndex = now.findIndex(isChecklistLine);
	if (nowIndex < 0) return null;
	const next = sectionLines(text, "Next");
	const done = sectionLines(text, "Done");
	const completed = stripTask((now.splice(nowIndex, 1)[0] as string).trim());
	done.push("- [x] " + completed);
	let promoted = "";
	const nextIndex = next.findIndex(isChecklistLine);
	if (nextIndex >= 0) {
		const line = (next.splice(nextIndex, 1)[0] as string).trim();
		promoted = stripTask(line);
		now.push(line);
	}
	let out = text;
	out = writeSection(out, "Now", now);
	out = writeSection(out, "Next", next);
	out = writeSection(out, "Done", done);
	out = touchPlan(out, "active", stamp);
	return { text: out, completed, promoted };
}

/** Unchecked tasks in the sections that must be finished before a plan is `done`. */
export function openPlanItems(text: string): string[] {
/** Structural checks for `.vibe-code/goals/*.md`. Pure. */
export function lintGoal(text: string): LintIssue[] {
	const all = text.split(/\r?\n/);
	const issues: LintIssue[] = [];
	if (!/^#\s*목표:\s*\S/m.test(text)) issues.push({ line: 0, message: "첫 줄은 `# 목표: <제목>` 형식이어야 합니다.", severity: "error" });
	for (const name of ["목표", "완료 기준", "현재 상태", "작업 큐", "검증 로그"]) {
		if (!hasSection(text, name)) issues.push({ line: 0, message: `\`## ${name}\` 섹션이 없습니다.`, severity: "warning" });
	}
	const status = matchLine(text, "상태");
	const statusLine = lineOf(all, (l) => /^상태:/.test(l));
	if (!status) issues.push({ line: 0, message: "`상태:` 줄이 없습니다 (draft | active | blocked | done).", severity: "warning" });
	else if (!STATUSES.includes(status.toLowerCase())) issues.push({ line: statusLine, message: `알 수 없는 상태 "${status}". draft | active | blocked | done 중 하나여야 합니다.`, severity: "error" });
	if (!matchLine(text, "- 다음 행동")) issues.push({ line: lineOf(all, (l) => /^## 현재 상태/.test(l)), message: "`- 다음 행동:` 줄이 비어 있습니다. 바로 할 일을 한 줄로 적으세요.", severity: "info" });
	const nowOpen = openTasks(subsection(text, "Now"));
	if (nowOpen > 4) issues.push({ line: lineOf(all, (l) => /^### Now/.test(l)), message: `Now에 미완료 항목이 ${nowOpen}개입니다. 4개 이하로 줄이고 나머지는 Next로 옮기세요.`, severity: "warning" });
	if (status.toLowerCase() === "done") {
		const open = openTasks(section(text, "완료 기준"));
		if (open > 0) issues.push({ line: statusLine, message: `상태가 done이지만 완료 기준 ${open}개가 체크되지 않았습니다.`, severity: "warning" });
	}
	return issues;
}

/** Structural checks for `.vibe-code/plans/*.md`. Pure. */
export function lintPlan(text: string): LintIssue[] {
	const all = text.split(/\r?\n/);
	const issues: LintIssue[] = [];
	if (!/^#\s*계획:\s*\S/m.test(text)) issues.push({ line: 0, message: "첫 줄은 `# 계획: <제목>` 형식이어야 합니다.", severity: "error" });
	for (const name of ["단계", "Now", "Next", "Done"]) {
		if (!hasSection(text, name)) issues.push({ line: 0, message: `\`## ${name}\` 섹션이 없습니다.`, severity: "warning" });
	}
	const status = matchLine(text, "상태");
	const statusLine = lineOf(all, (l) => /^상태:/.test(l));
	if (!status) issues.push({ line: 0, message: "`상태:` 줄이 없습니다 (draft | active | blocked | done).", severity: "warning" });
	else if (!STATUSES.includes(status.toLowerCase())) issues.push({ line: statusLine, message: `알 수 없는 상태 "${status}".`, severity: "error" });
	const priority = matchLine(text, "우선순위");
	if (priority && !PRIORITIES.includes(priority.toUpperCase())) issues.push({ line: lineOf(all, (l) => /^우선순위:/.test(l)), message: `알 수 없는 우선순위 "${priority}". P0 | P1 | P2 | P3`, severity: "error" });
	const nowOpen = openTasks(section(text, "Now"));
	if (nowOpen > 3) issues.push({ line: lineOf(all, (l) => /^## Now/.test(l)), message: `Now에 미완료 항목이 ${nowOpen}개입니다. 한 번에 1~3개만 두세요.`, severity: "warning" });
	if (status.toLowerCase() === "done") {
		const open = ["단계", "Now", "검증 계획"].reduce((n, name) => n + openTasks(section(text, name)), 0);
		if (open > 0) issues.push({ line: statusLine, message: `상태가 done이지만 미완료 항목이 ${open}개 있습니다.`, severity: "warning" });
	}
	if (!matchLine(text, "연결 목표")) issues.push({ line: lineOf(all, (l) => /^작성일:/.test(l)), message: "`연결 목표:` 줄이 없습니다. `현재 계획 목표 연결` 명령으로 목표와 연결하세요.", severity: "info" });
	return issues;
}

const SEVERITY = { error: vscode.DiagnosticSeverity.Error, warning: vscode.DiagnosticSeverity.Warning, info: vscode.DiagnosticSeverity.Information };

function kindOf(document: vscode.TextDocument): "goal" | "plan" | null {
			resolve({ exitCode: code, durationMs: Date.now() - started, output });
		});
	});
}

interface VerificationTarget {
	file: string;
	lineIndex?: number;
}

/** Run one command and record it in the target plan/goal file (and the goal file when a plan was targeted). */
async function runAndRecord(host: CoreHost, command: string, target: VerificationTarget | null): Promise<RunResult> {
	const ws = workspaceRoot() || process.cwd();
	const result = await runShellCommand(host, command, ws);
	const entry: VerificationEntry = { stamp: kstStamp().human, command, exitCode: result.exitCode, durationMs: result.durationMs };
	const line = formatVerificationLine(entry);
	const touched: string[] = [];
	const record = (file: string, tick?: number) => {
		if (!fs.existsSync(file)) return;
		let text = readUtf8(file);
		text = appendVerificationLog(text, line);
		if (tick !== undefined && result.exitCode === 0) text = checkLine(text, tick);
		text = touchPlan(text, null, entry.stamp);
		fs.writeFileSync(file, text, "utf8");
		touched.push(path.basename(file));
	};
	if (target) record(target.file, target.lineIndex);
	const paths = ensureWorkspacePaths(true);
	if (paths && fs.existsSync(paths.current) && (!target || path.resolve(target.file) !== path.resolve(paths.current))) record(paths.current);
	writeAudit(host, "plan", "runVerification", { command, exitCode: result.exitCode, durationMs: result.durationMs, recordedIn: touched });
	const label = result.exitCode === 0 ? "통과" : result.exitCode === null ? "시간 초과" : `실패 (exit ${result.exitCode})`;
	void (result.exitCode === 0 ? vscode.window.showInformationMessage : vscode.window.showWarningMessage)(`검증 ${label}: ${command}`);
	return result;
}

